const e={title:"TripReel - Aplicación Gratuita de Animación de Viajes: Convierte Fotos en Videos Hermosos",description:"Crea videos de viaje impresionantes con mapas animados y rutas de vuelo. Aplicación gratuita de animación de viajes con mapeo de ruta de globo 3D. Convierte tus fotos en videos de viaje hermosos automáticamente. Privacidad primero, funciona sin conexión.",keywords:"aplicación de animación de viajes, aplicación de animación de mapa de viajes, aplicación de animación de ruta de viajes, aplicación de animación de vuelo, creador de video de viajes, video de viaje automático, mapa de viaje animado, animación de ruta de vuelo, animación de viaje, animación de globo, video de recapitulación de viaje, foto a video, destacados de viaje, aplicación de viaje gratuita, creador de video sin conexión, aplicación de viaje privada, video de rollo de cámara"},a={logoAlt:"Logo de TripReel",appName:"TripReel",howItWorks:"Cómo funciona",video:"Vídeo",features:"Funciones",theApp:"La app"},i={badge:"Convierte fotos en historias de viaje",title1:"Tu galería,",title2:"totalmente aprovechada",description:"TripReel crea automáticamente preciosos vídeos de viaje desde las ubicaciones de tus fotos. Mira cómo tus viajes cobran vida con impresionantes mapas de rutas animadas y trayectorias de vuelo en un globo 3D, mientras tus datos permanecen privados y seguros.",secure:"100% seguro",worksOffline:"Funciona sin conexión",globeAlt:"Animación del globo TripReel"},o={title:"Cómo funciona",subtitle:"Tres pasos simples para crear tu vídeo de viaje perfecto",step1:{title:"Permitir acceso a fotos",description:"Concede a TripReel acceso a tu biblioteca de fotos. La app solo lee metadatos de ubicación, nada más."},step2:{title:"Detección automática de viajes",description:"TripReel analiza metadatos de ubicación y encuentra inteligentemente tus viajes según fechas y ubicaciones."},step3:{title:"Genera tu vídeo",description:"Observa cómo tu viaje se despliega en una preciosa animación del globo, lista para compartir en redes sociales."}},s={title:"Descubre la magia en acción",subtitle:"Mira cómo TripReel transforma tu biblioteca de fotos en increíbles vídeos de viaje",caption:"Así puede verse tu vídeo de viaje final"},t={title:"Todo lo que necesitas",subtitle:"Funciones potentes diseñadas para viajeros modernos",twoTap:{title:"Vídeos de viaje con dos toques",description:"Crea impresionantes vídeos de viaje desde tu biblioteca de fotos con solo dos toques. Sin edición necesaria."},smartTrip:{title:"Detección inteligente de viajes",description:"Encuentra y agrupa automáticamente tus viajes analizando fechas y metadatos de ubicación de tus fotos."},globe:{title:"Preciosa animación del globo",description:"Mira cómo tu viaje cobra vida con un impresionante globo 3D mostrando tus rutas de viaje animadas y trayectorias de vuelo por todo el mundo."},privacy:{title:"Privacidad primero",description:"Todo se procesa en tu dispositivo. Tus fotos nunca salen de tu teléfono. Funciona en modo avión."},customStyles:{title:"Estilos personalizados",description:"Elige entre múltiples estilos de globo y personalizaciones para adaptarse a tu estética y hacer cada vídeo único."},manualControl:{title:"Control manual",description:"Puedes añadir manualmente viajes completamente nuevos si los servicios de ubicación no estaban activados en tu dispositivo."}},n={title:"Ideas creativas de vídeos",subtitle:"Inspírate con lo que puedes crear usando TripReel. Desde escapadas rápidas de fin de semana hasta aventuras de un año, crea impresionantes vídeos de viaje para cada travesía.",description:"Ya sea que estés creando una animación de mapa de viaje, documentando una ruta de vuelo o haciendo un resumen anual de viajes, TripReel facilita transformar tus recuerdos en vídeos para compartir.",ideas:{yearRecap:{title:"Resumen de viajes 2025",description:"Crea automáticamente tu vídeo resumen anual de viajes 2025"},europeRoadTrip:{title:"Ruta por Europa",description:"Muestra tu aventura europea con mapas de rutas animadas"},southeastAsia:{title:"Viaje por el Sudeste Asiático",description:"Visualiza tu ruta mochilera a través de varios países"},japanRail:{title:"Viaje en tren por Japón",description:"Crea vídeos de mapas de tus rutas en tren por Japón"},crossCountry:{title:"De costa a costa en EE.UU.",description:"Convierte tu ruta americana en un épico vídeo de ruta"},islandHopping:{title:"Salto entre islas",description:"Muestra tus viajes de isla en isla con impresionantes animaciones 3D"},worldTour:{title:"Montaje de vuelta al mundo",description:"Múltiples viajes en un increíble vídeo de viaje global"},travelPlans:{title:"Planes de viaje 2026",description:"Visualiza y planifica tus emocionantes aventuras de viaje para 2026"},lifetimeTravel:{title:"Historia de viajes de toda una vida",description:"Crea un vídeo mostrando todos tus viajes de toda la vida"},regionalExplorer:{title:"Explorador regional",description:"Traza tus aventuras por estados, provincias y regiones"},festivalCircuit:{title:"Circuito de festivales",description:"Traza tu viaje de festivales de música y eventos"},bikeRoutes:{title:"Mis escapadas urbanas",description:"Muestra todas tus escapadas a la ciudad"}}},r={title:"La app",subtitle:"Disponible ahora en el App Store",alt1:"Vídeos de viaje automáticos - Crea vídeos impresionantes en segundos",alt2:"Detección de ubicación de fotos - Usa los metadatos de tus fotos",alt3:"Detección de viajes - Agrupa automáticamente tus viajes",alt4:"Preciosos vídeos del globo - Animación del globo de tu viaje",alt5:"Estilos personalizados - Personaliza tus vídeos de viaje"},d={comingSoon:"Próximamente",androidTitle:"¡App de Android próximamente!",androidMessage:'La versión de Android aún no está disponible pero lo estará pronto. Envíame un mensaje a <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> y te avisaré cuando esté lista!',gotIt:"¡Entendido!"},c={title:"Preguntas frecuentes",subtitle:"Todo lo que necesitas saber sobre TripReel",q1:{question:"¿Puedo realmente usar la app completamente en modo avión?",answer:"¡Sí! Para usuarios premium, la app puede usarse completamente sin conexión en modo avión sin limitaciones. Para usuarios no premium, algunas funciones están financiadas con anuncios que podrían requerir activar temporalmente internet, pero para usuarios premium no hay anuncios y la app puede usarse completamente en modo avión."},q2:{question:"Actualicé a Premium, ¿cómo puedo quitar la marca de agua?",answer:"Mucha gente pregunta qué app se usó para crear estos vídeos, así que después de actualizar a premium, tienes la opción de añadir una versión más pequeña de la marca de agua (solo con el nombre de la app) o quitarla completamente si lo deseas."},q3:{question:"¿Están seguros y privados los datos de mis fotos?",answer:"¡Absolutamente! TripReel solo lee metadatos de ubicación de tus fotos - nunca accedemos, almacenamos o transmitimos el contenido real de las fotos. Todo el procesamiento ocurre localmente en tu dispositivo, y ningún dato sale nunca de tu teléfono. Puedes verificar esto usando la app en modo avión - ¡funciona perfectamente sin conexión!"},q4:{question:"¿Qué pasa si mis fotos no tienen datos de ubicación?",answer:"¡No hay problema! Si los servicios de ubicación no estaban activados cuando tomaste tus fotos, puedes crear viajes manualmente y añadir ubicaciones tú mismo. La app te da control total para personalizar tu línea de tiempo de viajes."},q5:{question:"¿Cómo detecta la app mis viajes automáticamente?",answer:"TripReel analiza los metadatos de ubicación y las marcas de tiempo de tus fotos para identificar inteligentemente cuándo y dónde viajaste. Agrupa ubicaciones y fechas cercanas para detectar automáticamente tus viajes sin ningún trabajo manual."},q6:{question:"¿Puedo personalizar la apariencia de mis vídeos?",answer:"¡Sí! Puedes elegir entre múltiples estilos de globo y personalizar varios aspectos de tus vídeos de viaje animados para adaptarse a tu estética personal. Los usuarios premium obtienen acceso a estilos adicionales de animación de rutas, temas de mapas y opciones de trayectorias de vuelo."},q7:{question:"¿Necesito crear una cuenta?",answer:"¡No se requiere cuenta! TripReel funciona inmediatamente después de la descarga. No hay registro, no hay inicio de sesión y no se necesita información personal. Solo descarga la app y empieza a crear tus vídeos de viaje de inmediato."},q8:{question:"¿Por qué falta una ubicación en mi viaje?",answer:"La app solo puede trabajar con los datos disponibles, así que primero necesitas al menos un par de fotos en esa ubicación. Segundo, debes asegurarte de que tenías los datos de ubicación activados cuando estabas allí. Tercero, a veces la baja recepción de GPS puede causar datos de ubicación incorrectos. Si has descartado todo esto y tu ubicación aún no aparece, puedes añadir manualmente esa ubicación desde Resumen de viajes > botón Editar. Por favor usa también Contacto para reportar el problema."},q9:{question:"¿Dónde puedo compartir mi increíble vídeo?",answer:"Por supuesto, también puedes compartirlo en todas las plataformas sociales. Para adaptarse mejor a la plataforma, la app permite diferentes relaciones de aspecto para tus vídeos."},q10:{question:"¿Dónde puedo reportar un error?",answer:"Solo contáctame directamente en marian@qod.ee, explicando brevemente cuál es el problema."}},l={title:"Soporte por email",description:"Si tienes algún comentario o encuentras algún problema, no dudes en contactarme directamente a este email y leeré y gestionaré personalmente tu solicitud lo más rápido posible. ¡Gracias por usar la app!",close:"Cerrar"},u={default:{title:"🍪 Cookies",message:"Usamos cookies en el sitio de TripReel para mejorar tu experiencia. No se recopilan datos personales.",accept:"Aceptar",decline:"Rechazar",details:"Detalles"},theme:{title:"🍪 Cookies",message:"🌙 Para guardar tu preferencia de tema, necesitas aceptar cookies esenciales en el sitio de TripReel. Sin ellas, tu elección de tema no puede guardarse.",accept:"Aceptar",decline:"Rechazar",details:"Detalles"}},p={privacy:"Política de privacidad de la app",cookies:"Política de cookies del sitio",contact:"Contacto",cookiePreferences:"Preferencias de cookies",madeWith:"Hecho con",forTravelers:"para viajeros de todo el mundo",copyright:"© {{year}} TripReel."},m={title:"¿Listo para compartir tu viaje?",description:"Descarga TripReel hoy y transforma tu galería en preciosos vídeos de viaje con mapas y rutas animadas. Tus aventuras merecen ser celebradas.",features:"Descarga gratuita • Rápido y conveniente • Privacidad garantizada"},v={meta:e,header:a,hero:i,howItWorks:o,videoSection:s,features:t,videoIdeas:n,screenshots:r,appStore:d,faq:c,contact:l,cookieBanner:u,footer:p,cta:m};export{d as appStore,l as contact,u as cookieBanner,m as cta,v as default,c as faq,t as features,p as footer,a as header,i as hero,o as howItWorks,e as meta,r as screenshots,n as videoIdeas,s as videoSection};
